

def WithCallback(expectation, *callbacks):
    for callback in callbacks:
        expectation.append_callback(callback)
    return expectation


def Callback(callback_to_be_wrapped):
    def wrapped_callback(matcher, value, result):
        callback_to_be_wrapped()
    return wrapped_callback


def SucceededMatchingCallback(callback_to_be_wrapped):
    def wrapped_callback(matcher, value, result):
        if result:
            callback_to_be_wrapped()
    return wrapped_callback


def FailedMatchingCallback(callback_to_be_wrapped):
    def wrapped_callback(matcher, value, result):
        if not result:
            callback_to_be_wrapped()
    return wrapped_callback


def WithDynamicIds(expectation, *dynamic_ids):
    for dynamic_id in dynamic_ids:
        expectation = WithCallback(expectation, SucceededMatchingCallback(dynamic_id.save))
    return expectation
